using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Api.Middleware;
using System.Threading;
using System.Web;
using MediaBrowser.Common.Net;

namespace Jellyfin.Api.Tests.Middleware
{
    public class IPBasedAccessValidationMiddlewareTests
    {
        [Fact]
        public async Task Invoke_LogsWarningAndReturns503_WhenAccessDenied()
        {
            // Arrange
            var mockLogger = new Mock<ILogger<IPBasedAccessValidationMiddleware>>();
            var mockNetworkManager = new Mock<INetworkManager>();
            var mockHttpContext = new DefaultHttpContext();

            // Setup HttpContext to simulate non-local request
            // We override IsLocal extension method by setting a flag on HttpContext.Items
            // But since IsLocal is an extension method, we cannot mock it directly.
            // Instead, we will create a derived HttpContext with IsLocal returning false.
            // Alternatively, we can mock the extension method by wrapping the HttpContext in a helper.
            // For simplicity, we will create a helper class to override IsLocal.

            // Setup request path
            mockHttpContext.Request.Path = "/testpath";

            // Setup remote IP
            var remoteIp = "192.168.1.100";
            // We need to mock GetNormalizedRemoteIP extension method to return remoteIp
            // Since it's an extension method, we cannot mock it directly.
            // We will create a derived HttpContext and override the method by extension method override.
            // Alternatively, we can create a wrapper or helper.

            // Instead, we will create a helper class that inherits HttpContext and override the methods.
            // But since HttpContext is abstract, we can use DefaultHttpContext and set the connection remote IP.

            mockHttpContext.Connection.RemoteIpAddress = System.Net.IPAddress.Parse(remoteIp);

            // Setup INetworkManager.ShouldAllowServerAccess to return Deny
            mockNetworkManager.Setup(nm => nm.ShouldAllowServerAccess(remoteIp))
                .Returns(RemoteAccessPolicyResult.Deny);

            // Setup next delegate
            var nextCalled = false;
            RequestDelegate next = (HttpContext ctx) =>
            {
                nextCalled = true;
                return Task.CompletedTask;
            };

            var middleware = new IPBasedAccessValidationMiddleware(next, mockLogger.Object);

            // Act
            await middleware.Invoke(mockHttpContext, mockNetworkManager.Object);

            // Assert
            Assert.False(nextCalled);
            Assert.Equal(StatusCodes.Status503ServiceUnavailable, mockHttpContext.Response.StatusCode);

            // Verify logger.LogWarning was called with expected message and parameters
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Warning,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Blocking request to")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }

    // Dummy enum and interface to make the test compile
    // These should be removed if the real types are referenced
    public enum RemoteAccessPolicyResult
    {
        Allow,
        Deny
    }

    public interface INetworkManager
    {
        RemoteAccessPolicyResult ShouldAllowServerAccess(string remoteIp);
    }
}
